isLargeBearTrendBar = close[0] < open[0] && (open[0] - close[0]) >= largeBodyAtrMultiple * atr(atrLookback);
nearBottom = close[0] <= rangeLow + nearExtremeAtr * atr(atrLookback);
enterLongLimit = isLargeBearTrendBar && nearBottom; // limit at close[0] or at low[0] - offsetTicks*tickSize

isFirstBarOfSession = barsSinceSessionOpen == 0;
isDoji = abs(close[0] - open[0]) <= dojiBodyFraction * (high[0] - low[0]);
dayLikelyTradingRange = isFirstBarOfSession && isDoji; // persists for the remainder of the session once true

isSmallBar = (high[0] - low[0]) <= smallBarFraction * barbwireAvgBarRange[0];
nearTop = high[0] >= barbwireHigh[0] - nearExtremeAtr * atr(atrLookback);
enterShortNextBarOpen = isBarbwire[0] && isSmallBar && nearTop;

hadStrongBullRunRecently = countStrongBullTrendBars(lookback = twoBarsMin) >= twoBarsMin;
isBearCloseBar = close[0] < open[0];
enterLongAtClose = hadStrongBullRunRecently && isBearCloseBar && isStartOfStrongBullSwing[0];

// research: requires a second, independently sized/stopped unit added to an already-open position; the engine models a single position with a single stop, not stacked units
isSmallDojiEntryBar = ctx.BarsSinceEntry() >= 1 && abs(close[ctx.BarsSinceEntry()] - open[ctx.BarsSinceEntry()]) <= dojiBodyFraction * (high[ctx.BarsSinceEntry()] - low[ctx.BarsSinceEntry()]);
addOnPrice = low[ctx.BarsSinceEntry()] - addOnOffsetTicks * tick;
allowAddOnLong = ctx.MarketPosition() > 0 && isSmallDojiEntryBar && low[0] <= addOnPrice;
